before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>

enum Kind { WHOLE, FRACTION };
struct Number { enum Kind kind; union { int whole; double fraction; } value; };
int main(void) {
 struct Number n = {.kind = WHOLE, .value.whole = 7};
 if (n.kind == WHOLE) { printf("%d\n", n.value.whole); }
 else { printf("%.1f\n", n.value.fraction); }
}
```

